import{_ as s,a0 as o,w as i,s as l,ao as r,I as p,x as n,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"每日 Ubuntu 小技巧 - 更改 Ubuntu 使用语言 | LCTT x X-CMD","titleTemplate":false,"description":"每日 Ubuntu 小技巧 - 更改 Ubuntu 使用语言 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日 Ubuntu 小技巧 - 更改 Ubuntu 使用语言 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日 Ubuntu 小技巧 - 更改 Ubuntu 使用语言 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Daily Ubuntu Tips–Change The Language You Use In Ubuntu","title":"每日 Ubuntu 小技巧 - 更改 Ubuntu 使用语言","tag":"201312","desc":""},"relativePath":"201312/Daily Ubuntu Tips–Change The Language You Use In Ubuntu.md","filePath":"[post].md"}'),g={name:"201312/Daily Ubuntu Tips–Change The Language You Use In Ubuntu.md"};function b(d,t,T,m,U,C){const u=o("Link");return i(),l("div",null,[t[11]||(t[11]=r('<h1 id="每日-ubuntu-小技巧-更改-ubuntu-使用语言" tabindex="-1">每日 Ubuntu 小技巧 - 更改 Ubuntu 使用语言 <a class="header-anchor" href="#每日-ubuntu-小技巧-更改-ubuntu-使用语言" aria-label="Permalink to “每日 Ubuntu 小技巧 - 更改 Ubuntu 使用语言”">​</a></h1><p>Ubuntu 是一个功能强大的现代化操作系统，并且它还允许你使用多种语言的桌面。在默认情况下，在你第一次安装 Ubuntu 的时候会预装几个语言包。但如果你想要你的 Ubuntu 能够支持更多语言的话，那你就必须安装额外的语言包。通常不是所有的语言都是支持的，但是大多数使用中的语言以及书面语言都能够被支持。下面是一个是简短教程，它将会展示如何去实现。</p><p>在安装语言包之后，你可以根据你的语言重命名标准文件夹，例如音乐、图片和文档。你必须注销系统然后重新登录来使变更生效。当你重新登录之后，你会看到一个弹窗并且询问你是否愿意重命名这些标准文件夹，从而使得文件名满足你的所选择的语言要求。</p><p>要想更改 Ubuntu 的使用语言，单击菜单栏右上角的 <strong>齿轮</strong>，并且选择 <strong>System Settings（系统设置）</strong>。在打开 System Settings（系统设置） 之后，选择 <strong>Language Support（语言支持）</strong>。</p><p>如果提示要你安装额外的语言支持，那就直接安装。如果没有，那么就单击 Install / Remove （安装/删除）去安装新的语言包，然后，选择你想安装的语言来安装。最后，拖动新的语言到列表的顶端并且保存。这些更改只会应用在你的个人帐号上。如果你想应用在全局范围内，单击 <strong>Apply System-Wide（应用到全局设置）</strong> 。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/10/language-ubuntu.png" alt=""></p><p>拖动新的语言到列表的顶端。之后单击 Close。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/10/language-ubuntu-1.png" alt=""></p><p>关闭之后注销系统。然后重新登录，你就会看到更改生效了。</p><p>同样，语言包的更改只是应用在你的个人帐号上。如果你想全局更改的话，你必须单击 Apply System-Wide。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/10/language-ubuntu-2.png" alt=""></p><p>如果你选择了重命名标准文件夹，你必须重新登录才能看到变更。</p><p>好好享受吧！</p><hr>',14)),p("p",null,[t[1]||(t[1]=n("via: ",-1)),e(u,{href:"http://www.liberiangeek.net/2013/10/daily-ubuntu-tipschange-the-language-you-use-in-ubuntu/"},{default:a(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2013/10/daily-ubuntu-tipschange-the-language-you-use-in-ubuntu/",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=n("译者：",-1)),e(u,{href:"https://github.com/hyaocuk"},{default:a(()=>[...t[2]||(t[2]=[n("hyaocuk",-1)])]),_:1}),t[5]||(t[5]=n(" 校对：",-1)),e(u,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...t[3]||(t[3]=[n("Caroline",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=n("本文由 ",-1)),e(u,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原创翻译，",-1)),e(u,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[n("Linux中国",-1)])]),_:1}),t[10]||(t[10]=n(" 荣誉推出",-1))])])}const y=s(g,[["render",b]]);export{h as __pageData,y as default};
